        Internal.createCheck(this, DSL.name("principals_kind_check"), "((kind = ANY (ARRAY['human'::text, 'agent'::text])))", true),
        Internal.createCheck(this, DSL.name("principals_profile_name_check"), "(((length(profile_name) >= 1) AND (length(profile_name) <= 100)))", true),
        Internal.createCheck(this, DSL.name("principals_revision_check"), "((revision > 0))", true)
    )
    override fun `as`(alias: String): Principals = Principals(DSL.name(alias), this)
    override fun `as`(alias: Name): Principals = Principals(alias, this)
    override fun `as`(alias: Table<*>): Principals = Principals(alias.qualifiedName, this)

    override fun rename(name: String): Principals = Principals(DSL.name(name), null)

    override fun rename(name: Name): Principals = Principals(name, null)

    override fun rename(name: Table<*>): Principals = Principals(name.qualifiedName, null)

    override fun where(condition: Condition?): Principals = Principals(qualifiedName, if (aliased()) this else null, Internal.condition(this, condition))

    override fun where(conditions: Collection<Condition>): Principals = where(DSL.and(conditions))

    override fun where(vararg conditions: Condition?): Principals = where(DSL.and(*conditions))

    override fun where(condition: Field<Boolean?>?): Principals = where(DSL.condition(condition))

    @PlainSQL override fun where(condition: SQL): Principals = where(DSL.condition(condition))

    @PlainSQL override fun where(@Stringly.SQL condition: String): Principals = where(DSL.condition(condition))

    @PlainSQL override fun where(@Stringly.SQL condition: String, vararg binds: Any?): Principals = where(DSL.condition(condition, *binds))

    @PlainSQL override fun where(@Stringly.SQL condition: String, vararg parts: QueryPart): Principals = where(DSL.condition(condition, *parts))

    override fun whereExists(select: TableLike<*>): Principals = where(DSL.exists(select))

    override fun whereNotExists(select: TableLike<*>): Principals = where(DSL.notExists(select))
}
